package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.*;
import com.fasterxml.jackson.databind.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.containers.MySQLContainer;
import org.testcontainers.junit.jupiter.*;
import static org.junit.jupiter.api.Assertions.*;

@Testcontainers class JdbcVehiclePlanEvidenceTest {
    @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");static JdbcTemplate jdbc;
    VehiclePlanEvidence service;VehicleOwner owner;OperatorActor operator;ObjectMapper mapper=new ObjectMapper();
    @BeforeAll static void schema()throws Exception{var ds=new DriverManagerDataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());jdbc=new JdbcTemplate(ds);try(var c=ds.getConnection();var paths=Files.list(Path.of("..","docs","sql","migrations"))){for(var p:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(p));}}
    @BeforeEach void setup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_evidence_audit");for(String t:List.of("project_model_applicability","vehicle_health_observation","vehicle","model","series","brand","standard_project","operator_account","auth_session","user","audit_log","idempotency_record"))jdbc.update("DELETE FROM `"+t+"`");var manager=new DataSourceTransactionManager(jdbc.getDataSource());var integrity=new WriteIntegrityService(jdbc,mapper,manager);var db=new ReservationStore(jdbc,mapper,integrity,Clock.systemUTC(),manager);var ops=new OperatorIdentity(jdbc,null,manager);service=new VehiclePlanEvidence(db,ops,new HealthObservationService(jdbc,integrity,mapper,manager,Clock.systemUTC()),new ExperienceModeration(db,ops,false));
        jdbc.update("INSERT INTO user(id,openid,status) VALUES(1,'synthetic-evidence-owner',1)");jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,status,can_catalog,can_review) VALUES(1,'synthetic-catalog','unused','13800000000','ACTIVE',1,0)");String os=session("user","OWNER","test-app"),as=session("operator_account","OPERATOR",OperatorActor.APP);owner=new VehicleOwner(1,os,Instant.now().plusSeconds(3600));operator=new OperatorActor(1,as,Instant.now().plusSeconds(3600));
        jdbc.update("INSERT INTO brand(id,name,status) VALUES(1,'synthetic-brand',1)");jdbc.update("INSERT INTO series(id,brand_id,name,status) VALUES(1,1,'synthetic-series',1)");jdbc.update("INSERT INTO model(id,series_id,year,config_name,status) VALUES(1,1,'2026','A',1),(2,1,'2026','B',1)");jdbc.update("INSERT INTO vehicle(id,user_id,model_id,power_type,vin,plate_no) VALUES(1,1,1,'EV','SYNTHETICVIN','合成车牌'),(2,2,1,'EV',NULL,NULL),(3,1,NULL,'EV',NULL,NULL),(4,1,2,'EV',NULL,NULL)");jdbc.update("INSERT INTO standard_project(id,category,project_name,service_content,base_price_low,base_price_high,status) VALUES(1,1,'synthetic-project','合成服务内容',10,20,1)");
    }
    String session(String subject,String role,String app){String id=UUID.randomUUID().toString();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,refresh_hash,expires_at) VALUES(?,?,1,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",id,subject,role,app,UUID.randomUUID().toString());return id;}
    JsonNode input(String verdict,long version){var b=new LinkedHashMap<String,Object>();b.put("verdict",verdict);b.put("expected_version",version);b.put("source_reference",verdict.equals("WITHDRAW")?null:"合成来源，未验证真实性");return mapper.valueToTree(b);}
    JsonNode save(String verdict,long version,String key){return service.writeRule(operator,1,1,key,input(verdict,version));}
    Map<String,Object> evidence(long vehicle){return service.evidence(owner,new VehiclePlanEvidence.Request(vehicle,List.of(1L)));}
    Map<?,?> rule(long vehicle){return (Map<?,?>)((List<?>)evidence(vehicle).get("applicability")).get(0);}
    int status(Runnable r){return assertThrows(ResponseStatusException.class,r::run).getStatusCode().value();}
    @Test void privateProjectionAndUnknownDoNotInferFromPower(){var e=evidence(1);var v=(Map<?,?>)e.get("vehicle");assertEquals(Set.of("vehicle_id","model_id","model_name","model_source","power_type"),v.keySet());assertEquals("OWNER_REGISTERED",v.get("model_source"));assertEquals("UNKNOWN",rule(1).get("verdict"));assertEquals(6,((List<?>)((Map<?,?>)e.get("observations")).get("list")).size());assertEquals("UNKNOWN",rule(3).get("verdict"));assertNull(((Map<?,?>)evidence(3).get("vehicle")).get("model_id"));assertEquals(List.of(),((Map<?,?>)e.get("experiences")).get("items"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Integer.class));}
    @Test void onlyOwnActiveVehicleAndSessionAreReadable(){assertEquals(404,status(()->evidence(2)));jdbc.update("UPDATE vehicle SET is_deleted=1 WHERE id=1");assertEquals(404,status(()->evidence(1)));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,status(()->evidence(3)));}
    @Test void exactModelRulesWithdrawAndCachedReplayCannotRestore(){String key=UUID.randomUUID().toString();var original=save("NOT_APPLICABLE",0,key);assertEquals("NOT_APPLICABLE",rule(1).get("verdict"));assertEquals("UNKNOWN",rule(4).get("verdict"));save("WITHDRAW",1,UUID.randomUUID().toString());assertEquals(original,save("NOT_APPLICABLE",0,key));assertEquals("UNKNOWN",rule(1).get("verdict"));assertEquals(2L,((Number)service.readRule(operator,1,1).get("version")).longValue());assertNull(service.readRule(operator,1,1).get("rule"));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Integer.class));}
    @Test void permissionRevocationBlocksReadWriteAndCachedReplay(){String key=UUID.randomUUID().toString();save("APPLICABLE",0,key);jdbc.update("UPDATE operator_account SET can_catalog=0,can_review=1 WHERE id=1");assertEquals(403,status(()->service.readRule(operator,1,1)));assertEquals(403,status(()->save("APPLICABLE",0,key)));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Integer.class));}
    @Test void staleVersionAndChangedCatalogDoNotWrite(){save("APPLICABLE",0,UUID.randomUUID().toString());assertEquals(409,status(()->save("WITHDRAW",0,UUID.randomUUID().toString())));jdbc.update("UPDATE brand SET status=0 WHERE id=1");assertEquals("UNKNOWN",rule(1).get("verdict"));assertEquals(404,status(()->save("WITHDRAW",1,UUID.randomUUID().toString())));jdbc.update("UPDATE standard_project SET status=0 WHERE id=1");assertEquals(404,status(()->evidence(1)));}
    @Test void auditFailureRollsBackRuleAndIdempotency(){jdbc.execute("CREATE TRIGGER fail_evidence_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,status(()->save("APPLICABLE",0,UUID.randomUUID().toString())));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM project_model_applicability",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM idempotency_record",Integer.class));}
    @Test void strictSourceAndSafeVersionBoundaries(){for(String b:List.of("null","{\"vehicle_id\":1,\"project_ids\":[1,1]}","{\"vehicle_id\":1,\"project_ids\":[],\"vin\":\"x\"}"))assertEquals(400,status(()->VehiclePlanEvidence.request(b)));for(String s:List.of(" "," leading","a\nline","x".repeat(257),"a\u200db")){var b=input("APPLICABLE",0).deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)b).put("source_reference",s);assertEquals(400,status(()->VehiclePlanEvidence.ruleInput(b.toString())));}jdbc.update("INSERT INTO project_model_applicability(project_id,model_id,version,operator_id) VALUES(1,1,9007199254740991,1)");assertEquals(409,status(()->save("APPLICABLE",9007199254740991L,UUID.randomUUID().toString())));}
    @Test void sourceDeletionImmediatelyHidesMeasurementInLocalEvidence(){jdbc.update("DELETE FROM vehicle_archive");jdbc.update("INSERT INTO vehicle_archive(id,vehicle_id,archive_type,input_type,recorded_at) VALUES(1,1,1,3,'2026-01-01')");jdbc.update("INSERT INTO vehicle_health_observation(user_id,vehicle_id,metric,archive_id,archive_type,measurement_json,revision) VALUES(1,1,'OIL',1,1,?,1)","{\"measurement_name\":\"里程读数\",\"value\":\"100\",\"unit\":\"KM\",\"measured_on\":\"2026-01-01\",\"method\":\"本人抄录\",\"provenance\":\"OWNER_TRANSCRIBED\"}");var before=mapper.valueToTree(evidence(1)).path("observations").path("list").get(0);assertEquals("RECORDED_UNVERIFIED",before.path("status").textValue());assertEquals("100",before.path("measurement").path("value").textValue());jdbc.update("UPDATE vehicle_archive SET is_deleted=1 WHERE id=1");var after=mapper.valueToTree(evidence(1)).path("observations").path("list").get(0);assertEquals("SOURCE_UNAVAILABLE",after.path("status").textValue());assertEquals(0,after.path("measurement").size());assertTrue(after.path("archive_id").isNull());}
    @Test void twoCatalogOperatorsCannotBothPublishTheSameExpectedVersion()throws Exception{
        jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,status,can_catalog) VALUES(2,'synthetic-catalog-2','unused','13900000000','ACTIVE',1)");String s=UUID.randomUUID().toString();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,refresh_hash,expires_at) VALUES(?,'operator_account',2,'OPERATOR',?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",s,OperatorActor.APP,UUID.randomUUID().toString());var second=new OperatorActor(2,s,Instant.now().plusSeconds(3600));var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var start=new java.util.concurrent.CountDownLatch(1);
        try{var results=new ArrayList<java.util.concurrent.Future<Integer>>();for(var actor:List.of(operator,second))results.add(pool.submit(()->{start.await();try{service.writeRule(actor,1,1,UUID.randomUUID().toString(),input("APPLICABLE",0));return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var r:results)codes.add(r.get(30,java.util.concurrent.TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);assertEquals(1L,((Number)service.readRule(operator,1,1).get("version")).longValue());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log",Integer.class));}finally{pool.shutdownNow();}
    }
}
